p = Path("tools/strings_data.txt")
lines = p.read_text().splitlines()
out = []
filled = 0
missing = []
for line in lines:
    if not line.strip() or line.startswith("#"):
        out.append(line); continue
    parts = line.split("|")
    key = parts[0]
    if len(parts) < 8 and key in T:
        en, ru = parts[1], parts[2]
        uk, de, es, fr, zh = T[key]
        out.append("|".join([key, en, ru, uk, de, es, fr, zh]))
        filled += 1
    else:
        if len(parts) < 8:
            missing.append(key)
        out.append(line)
p.write_text("\n".join(out) + "\n")
print(f"filled {filled}; still short: {missing}")
